#include <cstdint>
#include <cstring>
#include <optional>
#include <string>
#include <vector>

struct Item { std::uint16_t id; std::uint8_t quantity; };
struct Save { std::string name; std::uint16_t level; float x, y; std::vector<Item> items; };

static std::uint32_t sum(const std::vector<std::uint8_t>& b, std::size_t n)
{
    std::uint32_t s{ 0 };
    for (std::size_t i{ 0 }; i < n; ++i) s += b[i];
    return s;
}

std::optional<Save> parseSave(const std::vector<std::uint8_t>& f)
{
    std::size_t at{ 0 };
    const auto need = [&](std::size_t n) { return at + n <= f.size(); };
    if (!need(7) || f[0] != 'S' || f[1] != 'A' || f[2] != 'V' || f[3] != 'E' || f[4] != 2 || f[5] != 0) return std::nullopt;
    at = 6;
    Save s{};
    const std::size_t nameLength{ f[at++] };
    if (!need(nameLength + 2 + 8 + 1)) return std::nullopt;
    s.name.assign(f.begin() + static_cast<std::ptrdiff_t>(at), f.begin() + static_cast<std::ptrdiff_t>(at + nameLength));
    at += nameLength;
    s.level = static_cast<std::uint16_t>(f[at] | (f[at + 1] << 8));
    at += 2;
    std::memcpy(&s.x, &f[at], 4);
    std::memcpy(&s.y, &f[at + 4], 4);
    at += 8;
    const std::size_t count{ f[at++] };
    if (!need(count * 3 + 4)) return std::nullopt;
    for (std::size_t i{ 0 }; i < count; ++i, at += 3)
        s.items.push_back({ static_cast<std::uint16_t>(f[at] | (f[at + 1] << 8)), f[at + 2] });
    std::uint32_t stored;
    std::memcpy(&stored, &f[at], 4);
    if (at + 4 != f.size() || stored != sum(f, at)) return std::nullopt;
    return s;
}

std::vector<std::uint8_t> writeSave(const Save& s)
{
    std::vector<std::uint8_t> b{ 'S', 'A', 'V', 'E', 2, 0, static_cast<std::uint8_t>(s.name.size()) };
    b.insert(b.end(), s.name.begin(), s.name.end());
    b.push_back(static_cast<std::uint8_t>(s.level & 0xFF));
    b.push_back(static_cast<std::uint8_t>(s.level >> 8));
    std::uint8_t f[8];
    std::memcpy(f, &s.x, 4);
    std::memcpy(f + 4, &s.y, 4);
    b.insert(b.end(), f, f + 8);
    b.push_back(static_cast<std::uint8_t>(s.items.size()));
    for (const Item& i : s.items)
    {
        b.push_back(static_cast<std::uint8_t>(i.id & 0xFF));
        b.push_back(static_cast<std::uint8_t>(i.id >> 8));
        b.push_back(i.quantity);
    }
    const std::uint32_t total{ sum(b, b.size()) };
    for (int k{ 0 }; k < 4; ++k) b.push_back(static_cast<std::uint8_t>(total >> (8 * k)));
    return b;
}

