using Bytes = std::vector<std::uint8_t>;
static const Bytes A{ 0x53, 0x41, 0x56, 0x45, 0x02, 0x00, 0x03, 0x41, 0x64, 0x61, 0x03, 0x00, 0x00, 0x00, 0xC8, 0x42, 0x00, 0x00, 0x20, 0xC0, 0x01, 0x07, 0x00, 0x05, 0x34, 0x04, 0x00, 0x00 };
static const Bytes C{ 0x53, 0x41, 0x56, 0x45, 0x02, 0x00, 0x03, 0x41, 0x64, 0x61, 0x03, 0x00, 0x00, 0x00, 0xC8, 0x42, 0x00, 0x00, 0x20, 0xC0, 0x02, 0x07, 0x00, 0x05, 0x2C, 0x01, 0x01, 0x63, 0x04, 0x00, 0x00 };

TEST("reading the samples") {
    const auto a{ parseSave(A) };
    CHECK(a.has_value());
    if (!a) return;
    CHECK_EQ(a->name, std::string("Ada"));
    CHECK_EQ(a->level, 3);
    CHECK_EQ(a->x, 100.0f); CHECK_EQ(a->y, -2.5f);
    CHECK_EQ(a->items.size(), 1u);
    if (!a->items.empty()) { CHECK_EQ(a->items[0].id, 7); CHECK_EQ(a->items[0].quantity, 5); }
    const auto c{ parseSave(C) };
    CHECK(c.has_value());
    if (c && c->items.size() == 2) { CHECK_EQ(c->items[1].id, 300); CHECK_EQ(c->items[1].quantity, 1); }
}
TEST("writing what the game writes") {
    CHECK(writeSave(Save{ "Ada", 3, 100.0f, -2.5f, { { 7, 5 } } }) == A);
    CHECK(writeSave(Save{ "Ada", 3, 100.0f, -2.5f, { { 7, 5 }, { 300, 1 } } }) == C);
}
TEST("round trips") {
    const Save s{ "Grace Hopper", 41, -12.75f, 3000.5f, { { 1, 99 }, { 65535, 1 }, { 512, 0 } } };
    const auto back{ parseSave(writeSave(s)) };
    CHECK(back.has_value());
    if (back) { CHECK_EQ(back->name, s.name); CHECK_EQ(back->level, 41); CHECK_EQ(back->y, 3000.5f); CHECK_EQ(back->items.size(), 3u); }
    const auto empty{ parseSave(writeSave(Save{ "", 1, 0.0f, 0.0f, {} })) };
    CHECK(empty.has_value());
}
TEST("rejecting damaged files") {
    Bytes badMagic{ A }; badMagic[0] = 'X';
    CHECK(!parseSave(badMagic).has_value());
    Bytes oldVersion{ A }; oldVersion[4] = 1;
    CHECK(!parseSave(oldVersion).has_value());
    Bytes edited{ A }; edited[23] = 99;
    CHECK(!parseSave(edited).has_value());
    CHECK(!parseSave(Bytes(A.begin(), A.end() - 1)).has_value());
    Bytes extra{ A }; extra.push_back(0);
    CHECK(!parseSave(extra).has_value());
    CHECK(!parseSave(Bytes{ 0x53, 0x41, 0x56, 0x45, 0x02, 0x00, 0x40, 0x41 }).has_value());
}

